import { z } from 'zod';
import { prisma } from '@adgeco/database';
import { assertTenant, authorise, encryptSecret, randomToken } from '@adgeco/auth';
import { config, tokenHash, context, event } from '../shared.js';
export const publishersRoutes = async (app) => {
    const publisherProfileSchema = z.object({ legalName: z.string().min(2).max(160), tradingName: z.string().min(2).max(160).optional(), website: z.string().url().optional(), countryCode: z.string().length(2).transform(v => v.toUpperCase()), registrationNumber: z.string().max(120).optional() });
    app.put('/v1/publishers/:organisationId/profile', async (req) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'publisher:manage'); const body = publisherProfileSchema.parse(req.body); const profile = await prisma.publisherProfile.upsert({ where: { organisationId }, create: { organisationId, ...body, status: 'PENDING_VERIFICATION' }, update: { ...body, status: 'PENDING_VERIFICATION' } }); await event('PublisherProfileSubmitted', organisationId, { publisherProfileId: profile.id }, req.id); return profile; });
    app.post('/v1/publishers/:organisationId/verifications', async (req, reply) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'publisher:manage'); const body = z.object({ verificationType: z.enum(['BUSINESS', 'INDIVIDUAL']), submittedData: z.record(z.unknown()) }).parse(req.body); const profile = await prisma.publisherProfile.findUnique({ where: { organisationId } }); if (!profile)
        return reply.code(404).send({ code: 'PUBLISHER_PROFILE_NOT_FOUND' }); const verification = await prisma.publisherVerification.create({ data: { publisherProfileId: profile.id, verificationType: body.verificationType, submittedData: body.submittedData, status: 'PENDING' } }); await event('PublisherVerificationSubmitted', organisationId, { verificationId: verification.id }, req.id); return reply.code(201).send(verification); });
    app.post('/v1/admin/publisher-verifications/:id/decision', async (req, reply) => { const ctx = await context(req); authorise(ctx, 'publisher:verify'); const { id } = z.object({ id: z.string().uuid() }).parse(req.params); const body = z.object({ status: z.enum(['APPROVED', 'REJECTED', 'NEEDS_INFORMATION']), reason: z.string().max(1000).optional() }).parse(req.body); const existing = await prisma.publisherVerification.findUnique({ where: { id }, include: { publisherProfile: true } }); if (!existing)
        return reply.code(404).send({ code: 'VERIFICATION_NOT_FOUND' }); const updated = await prisma.$transaction(async (tx) => { const v = await tx.publisherVerification.update({ where: { id }, data: { status: body.status, decisionReason: body.reason, reviewedByUserId: ctx.actorId, reviewedAt: new Date() } }); await tx.publisherProfile.update({ where: { id: existing.publisherProfileId }, data: { status: body.status === 'APPROVED' ? 'ACTIVE' : body.status === 'REJECTED' ? 'REJECTED' : 'PENDING_VERIFICATION' } }); return v; }); await event('PublisherVerificationDecided', existing.publisherProfile.organisationId, { verificationId: id, status: body.status }, req.id); return updated; });
    const propertyBody = z.object({ type: z.enum(['WEBSITE', 'MOBILE_APP', 'MOBILE_GAME']), name: z.string().min(2), externalIdentifier: z.string().min(2), domain: z.string().optional(), storeUrl: z.string().url().optional(), packageName: z.string().optional(), bundleId: z.string().optional(), gameEngine: z.string().optional(), category: z.string().min(2), language: z.string().default('en'), countryCodes: z.array(z.string().length(2)).min(1) }).superRefine((v, c) => { if (v.type === 'WEBSITE' && !v.domain)
        c.addIssue({ code: 'custom', message: 'domain is required for websites' }); if (v.type === 'MOBILE_APP' && !v.packageName && !v.bundleId)
        c.addIssue({ code: 'custom', message: 'packageName or bundleId is required' }); if (v.type === 'MOBILE_GAME' && !v.gameEngine)
        c.addIssue({ code: 'custom', message: 'gameEngine is required' }); });
    app.post('/v1/publishers/:organisationId/properties', async (req, reply) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'property:manage'); const body = propertyBody.parse(req.body); const property = await prisma.property.create({ data: { organisationId, ...body, countryCodes: body.countryCodes.map(v => v.toUpperCase()), status: 'PENDING_VERIFICATION' } }); await event('PropertyRegistered', organisationId, { propertyId: property.id, type: property.type }, req.id); return reply.code(201).send(property); });
    app.get('/v1/publishers/:organisationId/properties', async (req) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'publisher:read'); return prisma.property.findMany({ where: { organisationId }, include: { placements: true, sdkRegistrations: { select: { id: true, platform: true, sdkVersion: true, status: true, lastHeartbeatAt: true, certifiedAt: true } } }, orderBy: { createdAt: 'desc' } }); });
    app.post('/v1/publishers/:organisationId/inventory-policies', async (req, reply) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'placement:manage'); const body = z.object({ name: z.string().min(2), floorCpm: z.coerce.number().min(0).optional(), currency: z.string().length(3).default('USD'), blockedCategories: z.array(z.string()).default([]), blockedAdvertiserDomains: z.array(z.string()).default([]), allowedCountryCodes: z.array(z.string().length(2)).default([]), requireBrandSafety: z.boolean().default(true) }).parse(req.body); return reply.code(201).send(await prisma.inventoryPolicy.create({ data: { organisationId, ...body, currency: body.currency.toUpperCase(), allowedCountryCodes: body.allowedCountryCodes.map(v => v.toUpperCase()) } })); });
    app.post('/v1/properties/:propertyId/placements', async (req, reply) => { const ctx = await context(req); const { propertyId } = z.object({ propertyId: z.string().uuid() }).parse(req.params); const property = await prisma.property.findUnique({ where: { id: propertyId } }); if (!property)
        return reply.code(404).send({ code: 'PROPERTY_NOT_FOUND' }); assertTenant(ctx, property.organisationId); authorise(ctx, 'placement:manage'); const body = z.object({ name: z.string().min(2), format: z.enum(['BANNER', 'INTERSTITIAL', 'REWARDED_VIDEO', 'NATIVE', 'PLAYABLE', 'IN_FEED', 'SPLASH', 'FULLSCREEN', 'CUSTOM']), inventoryPolicyId: z.string().uuid().optional(), width: z.number().int().positive().optional(), height: z.number().int().positive().optional(), rewardName: z.string().optional(), rewardAmount: z.number().int().positive().optional(), floorCpm: z.coerce.number().min(0).optional(), currency: z.string().length(3).default('USD') }).parse(req.body); const placement = await prisma.placement.create({ data: { propertyId, ...body, currency: body.currency.toUpperCase(), status: 'PENDING_REVIEW' } }); await event('PlacementCreated', property.organisationId, { propertyId, placementId: placement.id }, req.id); return reply.code(201).send(placement); });
    app.post('/v1/properties/:propertyId/sdk-registrations', async (req, reply) => { const ctx = await context(req); const { propertyId } = z.object({ propertyId: z.string().uuid() }).parse(req.params); const property = await prisma.property.findUnique({ where: { id: propertyId } }); if (!property)
        return reply.code(404).send({ code: 'PROPERTY_NOT_FOUND' }); assertTenant(ctx, property.organisationId); authorise(ctx, 'property:manage'); const body = z.object({ platform: z.enum(['WEB', 'ANDROID', 'IOS', 'UNITY']), sdkVersion: z.string().min(1), environment: z.enum(['SANDBOX', 'PRODUCTION']).default('SANDBOX') }).parse(req.body); const prefix = `pub_${randomToken(6)}`; const secret = randomToken(32); const registration = await prisma.sdkRegistration.create({ data: { organisationId: property.organisationId, propertyId, platform: body.platform, sdkVersion: body.sdkVersion, environment: body.environment, publicKeyPrefix: prefix, secretHash: tokenHash(`${prefix}.${secret}`) } }); await event('SdkRegistrationCreated', property.organisationId, { sdkRegistrationId: registration.id, propertyId }, req.id); return reply.code(201).send({ ...registration, sdkKey: `${prefix}.${secret}` }); });
    app.post('/v1/sdk-registrations/:id/heartbeat', async (req, reply) => { const { id } = z.object({ id: z.string().uuid() }).parse(req.params); const key = z.string().min(10).parse(req.headers['x-adgeco-sdk-key']); const registration = await prisma.sdkRegistration.findUnique({ where: { id } }); if (!registration || registration.secretHash !== tokenHash(key) || ['SUSPENDED', 'REVOKED'].includes(registration.status))
        return reply.code(401).send({ code: 'INVALID_SDK_CREDENTIAL' }); const updated = await prisma.sdkRegistration.update({ where: { id }, data: { lastHeartbeatAt: new Date(), status: registration.status === 'REGISTERED' ? 'TESTING' : registration.status } }); return { accepted: true, status: updated.status }; });
    app.put('/v1/publishers/:organisationId/payout-profile', async (req) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'payout:manage'); const body = z.object({ provider: z.string().min(2), accountReference: z.string().min(4), currency: z.string().length(3).default('USD'), countryCode: z.string().length(2), schedule: z.enum(['WEEKLY', 'BIWEEKLY', 'MONTHLY']).default('MONTHLY'), minimumThreshold: z.coerce.number().min(1).default(100), taxIdentifier: z.string().optional() }).parse(req.body); return prisma.publisherPayoutProfile.upsert({ where: { organisationId }, create: { organisationId, provider: body.provider, accountReferenceEncrypted: encryptSecret(body.accountReference, config.tokenPepper), currency: body.currency.toUpperCase(), countryCode: body.countryCode.toUpperCase(), schedule: body.schedule, minimumThreshold: body.minimumThreshold, taxIdentifierEncrypted: body.taxIdentifier ? encryptSecret(body.taxIdentifier, config.tokenPepper) : undefined, status: 'PENDING_VERIFICATION' }, update: { provider: body.provider, accountReferenceEncrypted: encryptSecret(body.accountReference, config.tokenPepper), currency: body.currency.toUpperCase(), countryCode: body.countryCode.toUpperCase(), schedule: body.schedule, minimumThreshold: body.minimumThreshold, taxIdentifierEncrypted: body.taxIdentifier ? encryptSecret(body.taxIdentifier, config.tokenPepper) : undefined, status: 'PENDING_VERIFICATION' } }); });
    app.get('/v1/publishers/:organisationId/dashboard', async (req) => { const ctx = await context(req); const { organisationId } = z.object({ organisationId: z.string().uuid() }).parse(req.params); assertTenant(ctx, organisationId); authorise(ctx, 'publisher:read'); const [profile, properties, placements, sdks, payout] = await Promise.all([prisma.publisherProfile.findUnique({ where: { organisationId } }), prisma.property.count({ where: { organisationId } }), prisma.placement.count({ where: { property: { organisationId } } }), prisma.sdkRegistration.findMany({ where: { organisationId }, select: { id: true, platform: true, status: true, lastHeartbeatAt: true, certifiedAt: true } }), prisma.publisherPayoutProfile.findUnique({ where: { organisationId }, select: { status: true, currency: true, schedule: true, minimumThreshold: true } })]); return { profile, metrics: { properties, placements, activeSdks: sdks.filter(s => s.status === 'ACTIVE').length, certifiedSdks: sdks.filter(s => s.certifiedAt).length }, sdkHealth: sdks, payoutProfile: payout }; });
};
